import{_ as t,o as s,c as e,a3 as o}from"./chunks/framework.qCVWde4n.js";const b=JSON.parse('{"title":"浏览与安装（玩家）","description":"","frontmatter":{},"headers":[],"relativePath":"repo/browse.md","filePath":"repo/browse.md","lastUpdated":1791133906000}'),n={name:"repo/browse.md"};function r(l,a,i,d,p,c){return s(),e("div",null,[...a[0]||(a[0]=[o(`<h1 id="浏览与安装-玩家" tabindex="-1">浏览与安装（玩家） <a class="header-anchor" href="#浏览与安装-玩家" aria-label="Permalink to &quot;浏览与安装（玩家）&quot;">​</a></h1><p>这一页教你怎么从仓库里找到并装上别人做的 Mod。</p><h2 id="打开仓库" tabindex="-1">打开仓库 <a class="header-anchor" href="#打开仓库" aria-label="Permalink to &quot;打开仓库&quot;">​</a></h2><p>手机或电脑浏览器打开：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://atlanticfleet.asia/mods/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>不用装任何东西，直接就能访问。</p><h2 id="找到想要的-mod" tabindex="-1">找到想要的 Mod <a class="header-anchor" href="#找到想要的-mod" aria-label="Permalink to &quot;找到想要的 Mod&quot;">​</a></h2><ul><li><strong>搜索框</strong> —— 输入名字、作者、说明里的词、或标签都能搜到</li><li><strong>排序</strong> —— 切成「<strong>最新</strong>」看新上架的，「<strong>最热</strong>」看舰船 / 编队 / 参数最多的，「<strong>名称</strong>」按字母排</li><li><strong>刷新</strong> —— 别人刚上传的 Mod，点一下刷新就能看到</li></ul><h2 id="看清楚这个-mod-是什么" tabindex="-1">看清楚这个 Mod 是什么 <a class="header-anchor" href="#看清楚这个-mod-是什么" aria-label="Permalink to &quot;看清楚这个 Mod 是什么&quot;">​</a></h2><p>点卡片上的「<strong>详情</strong>」，弹出的层里会显示：</p><ul><li>完整说明（作者写的一句话介绍）</li><li>作者、版本、包体大小</li><li>舰船数、编队数</li><li><strong>★ 它改了哪些参数</strong> —— 自动从 <code>mod.json</code> 里读出来，每一项还标了<strong>调高 ↑</strong> 还是<strong>调低 ↓</strong>，一眼看出这是「+35% 主炮伤害」还是「纯换模型」</li><li>这个 Mod 的<strong>分享码</strong>（完整文本，可手动复制）</li></ul><div class="tip custom-block"><p class="custom-block-title">装之前先看参数表</p><p>这是最容易踩坑的地方。有些 Mod 看起来是「美化」，其实改了一大堆数值。装之前扫一眼参数表，心里有数。</p></div><h2 id="安装-两种方式" tabindex="-1">安装：两种方式 <a class="header-anchor" href="#安装-两种方式" aria-label="Permalink to &quot;安装：两种方式&quot;">​</a></h2><h3 id="方式一-分享码-推荐-最省事" tabindex="-1">方式一：分享码（推荐，最省事） <a class="header-anchor" href="#方式一-分享码-推荐-最省事" aria-label="Permalink to &quot;方式一：分享码（推荐，最省事）&quot;">​</a></h3><ol><li>在卡片上直接点「<strong>复制分享码</strong>」（或在详情里点），码进剪贴板</li><li>打开游戏 → 点「小u」→「<strong>参数</strong>」页 →「<strong>粘贴导入分享码</strong>」</li><li><strong>完全退出游戏，重开</strong> → Mod 生效</li></ol><p>也支持一次性粘贴<strong>多条码</strong>（网页上连续复制几次，游戏会自动按前缀切分逐条导入）。</p><h3 id="方式二-下载包体手动装" tabindex="-1">方式二：下载包体手动装 <a class="header-anchor" href="#方式二-下载包体手动装" aria-label="Permalink to &quot;方式二：下载包体手动装&quot;">​</a></h3><p>适合电脑上操作、或想自己改一改的情况。</p><ol><li>在详情里点「<strong>下载包体</strong>」</li><li>找到游戏私有目录下的 <code>mods/</code></li><li>新建一个文件夹（别用 <code>_</code> 开头），把 <code>mod.json</code> 放进去</li><li>重开游戏</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mods/</span></span>
<span class="line"><span>└── 从网页下载的Mod/</span></span>
<span class="line"><span>    └── mod.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="装完确认一下" tabindex="-1">装完确认一下 <a class="header-anchor" href="#装完确认一下" aria-label="Permalink to &quot;装完确认一下&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查</th><th>在哪看</th></tr></thead><tbody><tr><td>Mod 有没被识别</td><td>「小u」→「Mod」页，应能看到你的 Mod + 作者 + 版本</td></tr><tr><td>参数有没有生效</td><td>「参数」页 / 「状态」页的「偏离原版的参数」清单</td></tr><tr><td>有没有报错</td><td>「日志」页筛「错误」</td></tr><tr><td>模型加载了吗</td><td>「Mod」页底部模型自检</td></tr></tbody></table><h2 id="自己也想传一个" tabindex="-1">自己也想传一个？ <a class="header-anchor" href="#自己也想传一个" aria-label="Permalink to &quot;自己也想传一个？&quot;">​</a></h2><p>仓库向所有人开放上传。流程见 → <a href="/AtlanticFleetSite/docs/repo/publish">上传你的 Mod（作者）</a></p>`,24)])])}const u=t(n,[["render",r]]);export{b as __pageData,u as default};
